const stages=[{k:'HYPATIA + HYPERIA',t:'Discover what is true—and what is still unknown.',c:'Rank hypotheses, synthesize sources, and label every consequential claim as Observed, Derived, Assumed, or Unknown.',l:['Evidence ledger','Competing explanations','Discriminating measurement plan']},{k:'INTELLIGENT ENGINEER',t:'Convert validated knowledge into verifiable options.',c:'Preserve requirements, interfaces, assumptions, failure modes, and configuration state while evaluating alternatives.',l:['Trade study','Interface model','Verification matrix']},{k:'GROUND-TRUTH GATEKEEPER',t:'Test the work before the work moves on.',c:'Recompute critical values, inspect provenance, execute acceptance tests, and block unsupported promotion.',l:['Pass / conditional pass / fail','Independent checks','Exact remediation']},{k:'PM ACCELERATOR + VIBE ENGINEERING',t:'Deliver owned, reproducible work.',c:'Turn approved decisions into executable packages with clear owners, rollback, and closure evidence.',l:['Owned milestones','Reproducible release','Approval record']},{k:'MISSION MEMORY STEWARD',t:'Make outcomes improve the next process.',c:'Record validated facts and decisions, measure results, and version approved playbook changes without rewriting history.',l:['Durable state','Outcome review','Versioned evolution']}];document.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-stage]').forEach(x=>x.setAttribute('aria-selected','false'));b.setAttribute('aria-selected','true');let s=stages[+b.dataset.stage];stageKicker.textContent=s.k;stageTitle.textContent=s.t;stageCopy.textContent=s.c;stageList.innerHTML=s.l.map(x=>`<li>${x}</li>`).join('')}));document.getElementById('filter').addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.download-list li').forEach(li=>li.hidden=!li.textContent.toLowerCase().includes(q))});